package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	num := false
	var files []string
	for _, a := range os.Args[1:] {
		if a == "-n" {
			num = true
		} else {
			files = append(files, a)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := 0
	emit := func(data string) {
		if !num {
			w.WriteString(data)
			return
		}
		for len(data) > 0 {
			i := strings.IndexByte(data, '\n')
			var line string
			if i < 0 {
				line, data = data, ""
			} else {
				line, data = data[:i], data[i+1:]
			}
			n++
			fmt.Fprintf(w, "%6d\t%s\n", n, line)
		}
	}
	code := 0
	if len(files) == 0 {
		b, _ := io.ReadAll(os.Stdin)
		emit(string(b))
	}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			fmt.Fprintf(w, "cat: %s: No such file\n", f)
			code = 1
			continue
		}
		emit(string(b))
	}
	w.Flush()
	os.Exit(code)
}
